SELECT event_id AS eventId,node_id AS nodeId,status,attempt_count AS attemptCount,
  recovery_attempt_count AS recoveryAttemptCount,recovery_actor AS recoveryActor,last_error AS lastError,updated_at AS updatedAt
FROM fcc_event_inbox WHERE status IN ('UNKNOWN','RECOVERING') ORDER BY updated_at,event_id LIMIT 50 OFFSET #{offset}

SELECT status
FROM fcc_event_inbox
WHERE event_id = #{id}
